/** Additive inventory journal. Writes are generated by transactional database
 * triggers; runtime roles have only seller-scoped SELECT on these tables. */
import { index, integer, pgTable, text, timestamp, uniqueIndex, uuid } from 'drizzle-orm/pg-core';
import { sql } from 'drizzle-orm';
import { products } from './catalogue';
import { sellers } from './sellers';
import { orderLineItems, subOrders } from './orders';
export const inventoryReservations = pgTable('inventory_reservations', {
  id: uuid('id').primaryKey().defaultRandom(),
  lineItemId: uuid('line_item_id').notNull().unique().references(() => orderLineItems.id),
  subOrderId: uuid('sub_order_id').notNull().references(() => subOrders.id),
  productId: uuid('product_id').notNull().references(() => products.id),
  sellerId: uuid('seller_id').notNull().references(() => sellers.id),
  quantity: integer('quantity').notNull(), state: text('state').notNull().default('active'),
  createdAt: timestamp('created_at',{withTimezone:true}).notNull().defaultNow(),
  closedAt: timestamp('closed_at',{withTimezone:true}),
}, t => [index('inventory_reservations_active_product_idx').on(t.productId).where(sql`${t.state}='active'`),
  index('inventory_reservations_sub_order_idx').on(t.subOrderId,t.state), index('inventory_reservations_seller_idx').on(t.sellerId)]);
export const inventoryMovements = pgTable('inventory_movements', {
  id: uuid('id').primaryKey().defaultRandom(), productId: uuid('product_id').notNull().references(() => products.id),
  sellerId: uuid('seller_id').notNull().references(() => sellers.id), lineItemId: uuid('line_item_id').references(() => orderLineItems.id),
  kind: text('kind').notNull(), deltaOnHand: integer('delta_on_hand').notNull(), deltaReserved: integer('delta_reserved').notNull(),
  reason: text('reason').notNull(), stockBefore: integer('stock_before'), stockAfter: integer('stock_after'),
  requestId: uuid('request_id'), actorId: uuid('actor_id'), occurredAt: timestamp('occurred_at',{withTimezone:true}).notNull().defaultNow(),
}, t => [index('inventory_movements_product_time_idx').on(t.productId,t.occurredAt.desc(),t.id.desc()),
  index('inventory_movements_seller_idx').on(t.sellerId),
  uniqueIndex('inventory_movements_adjust_request_key').on(t.sellerId,t.requestId).where(sql`${t.requestId} IS NOT NULL`)]);
